mapper.select:
SELECT C.CREDIT_ID, C.CONTENT_ID, C.SEASON_ID, C.NAME, C.CHAR_NAME, C.PROFILE_IMAGE_URL
FROM CONTENT_CREDIT C
WHERE C.CONTENT_ID = #{id}

SELECT E.EPISODE_ID, E.SEASON_NO, E.EPISODE_NO, E.TITLE, E.SUMMARY, E.STILL_IMAGE_URL
FROM CONTENT_EPISODE E
WHERE E.CONTENT_ID = #{contentId}
  AND E.SEASON_NO = #{seasonNo}
ORDER BY E.EPISODE_NO

SELECT C.CREDIT_ID, C.CONTENT_ID, C.SEASON_ID, C.NAME, C.CHAR_NAME, C.PROFILE_IMAGE_URL
FROM CONTENT_CREDIT C
INNER JOIN CONTENT_SEASON S ON S.SEASON_ID = C.SEASON_ID
WHERE S.CONTENT_ID = #{contentId}
  AND S.SEASON_NO = #{seasonNo}

SELECT C.CONTENT_ID
FROM CONTENT C
WHERE C.TMDB_ID = #{tmdbId}
  AND C.CONTENT_TYPE = #{contentType}

SELECT S.SEASON_ID
FROM CONTENT_SEASON S
WHERE S.CONTENT_ID = #{contentId}
  AND S.SEASON_NO = #{seasonNo}
